// Função genérica que preserva o tipo passado
function primeiroItem<T>(lista: T[]): T | undefined {
  return lista[0];
}

// Função assíncrona tipada
async function buscarPerfil(id: string): Promise<{ nome: string }> {
  const res = await fetch(`/api/users/${id}`);
  return await res.json();
}
